import { useState } from "react";
import { useNavigate } from "react-router-dom";
import { Eye, EyeOff, User } from "lucide-react";
import { LogoSeal } from "../components/Layout";

export default function Login({ onLogin }) {
  const navigate = useNavigate();
  const [form, setForm] = useState({ usuario:"carlos.mendez", password:"" });
  const [showPass, setShowPass] = useState(false);
  const [cargando, setCargando] = useState(false);
  const [error, setError] = useState(null);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!form.usuario || !form.password) { setError("Ingrese usuario y contraseña."); return; }
    setCargando(true); setError(null);
    await new Promise(r => setTimeout(r, 1000));
    onLogin({ nombre:"Carlos Méndez", rol:"Operador", initials:"CM" });
    navigate("/dashboard");
    setCargando(false);
  };

  return (
    <div style={{ display:"flex", minHeight:"100vh", background:"#0a1628" }}>
      {/* Izquierda */}
      <div style={{ width:"50%", display:"flex", flexDirection:"column", justifyContent:"space-between", padding:"48px 64px", position:"relative", zIndex:2 }}>
        <LogoSeal size="lg" />
        <div style={{ maxWidth:400 }} className="fade-up">
          <p style={{ fontSize:11, fontWeight:700, letterSpacing:"0.14em", color:"rgba(255,255,255,0.50)", textTransform:"uppercase", marginBottom:16 }}>Sistema de Calidad</p>
          <h1 style={{ fontFamily:"'Playfair Display',serif", fontSize:44, fontWeight:800, letterSpacing:"-0.02em", lineHeight:1.1, marginBottom:10 }}>
            Bienvenido<br/>de nuevo.
          </h1>
          <p style={{ fontSize:14, color:"rgba(255,255,255,0.50)", marginBottom:36 }}>
            ¿No tiene cuenta?{" "}
            <span style={{ color:"#6a9fd8", textDecoration:"underline", cursor:"pointer" }}>Contacte al administrador</span>
          </p>
          {error && (
            <div style={{ background:"rgba(231,76,60,0.12)", border:"1px solid rgba(231,76,60,0.30)", borderRadius:8, padding:"12px 16px", fontSize:13, color:"#fca5a5", marginBottom:16 }}>{error}</div>
          )}
          <form onSubmit={handleSubmit} style={{ display:"flex", flexDirection:"column", gap:16 }}>
            <div>
              <label style={{ display:"block", fontSize:12, color:"rgba(255,255,255,0.55)", marginBottom:8 }}>Usaario</label>
              <div style={{ position:"relative" }}>
                <input className="input-navy" value={form.usuario} onChange={e=>setForm(p=>({...p,usuario:e.target.value}))} placeholder="su.usuario" autoComplete="username"/>
                <User size={15} color="rgba(255,255,255,0.35)" style={{ position:"absolute", right:14, top:"50%", transform:"translateY(-50%)", pointerEvents:"none" }}/>
              </div>
            </div>
            <div>
              <label style={{ display:"block", fontSize:12, color:"rgba(255,255,255,0.55)", marginBottom:8 }}>Contraseña</label>
              <div style={{ position:"relative" }}>
                <input className="input-navy" type={showPass?"text":"password"} value={form.password} onChange={e=>setForm(p=>({...p,password:e.target.value}))} placeholder="••••••••" autoComplete="current-password"/>
                <button type="button" onClick={()=>setShowPass(!showPass)} style={{ position:"absolute", right:14, top:"50%", transform:"translateY(-50%)", background:"none", border:"none", cursor:"pointer", color:"rgba(255,255,255,0.45)" }}>
                  {showPass?<EyeOff size={15}/>:<Eye size={15}/>}
                </button>
              </div>
            </div>
            <button type="submit" disabled={cargando} className="btn-navy" style={{ width:"100%", padding:"13px", fontSize:15, marginTop:6 }}>
              {cargando ? <span className="spinner" style={{width:18,height:18}}/> : "Iniciar Sesión"}
            </button>
          </form>
        </div>
        <p style={{ fontSize:12, color:"rgba(255,255,255,0.25)" }}>v1.0 © 2025 Lácteos de Oriente — Guatemala</p>
      </div>
      {/* Derecha — foto */}
      <div style={{ width:"50%", position:"relative", overflow:"hidden" }}>
        <div className="bg-farm-photo" style={{ position:"absolute", inset:0 }}/>
        <div style={{ position:"absolute", inset:0, background:"linear-gradient(to right,#0a1628 0%,rgba(10,22,40,0.25) 100%)" }}/>
      </div>
    </div>
  );
}
